policy.source:
def investigate(context, acquire):
    receipts = context.get('receipts', [])
    seen = set()
    for row in receipts:
        query = row.get('query')
        if isinstance(query, dict):
            key = tuple(sorted((a.get('op'), a.get('id')) for a in query.get('actions', [])))
            seen.add(key)
    actions = [{'op': 'put', 'id': 5}, {'op': 'begin'}, {'op': 'put', 'id': 2}, {'op': 'rollback'}]
    key = tuple(sorted((a.get('op'), a.get('id')) for a in actions))
    if key in seen:
        actions = [{'op': 'put', 'id': 1}, {'op': 'begin'}, {'op': 'put', 'id': 3}, {'op': 'rollback'}]
    return {'query': {'actions': actions}, 'note': {'hypothesis': 'AUTOINCREMENT sqlite_sequence is transaction durable; rollback does not lower the high-water mark'}}

candidate.source:
def investigate(context, acquire):
    actions = context.get('actions', [])
    committed = set()
    pending = None
    high = 0
    for action in actions:
        op = action.get('op')
        if op == 'put':
            ident = action.get('id')
            if pending is None:
                committed.add(ident)
            else:
                pending.add(ident)
            if ident > high:
                high = ident
        elif op == 'delete':
            ident = action.get('id')
            if pending is None:
                committed.discard(ident)
            else:
                pending.discard(ident)
        elif op == 'begin':
            pending = set(committed)
        elif op == 'commit':
            committed = set(pending)
            pending = None
        elif op == 'rollback':
            pending = None
            if committed:
                high = max(committed)
    return high + 1

